#' Simulated driving-simulator study (`driving_sim.csv`)
#'
#' Simulated take-over study: 40 participants each respond to take-over
#' requests (TOR) under three warning modalities, four trials per
#' modality (within design, 480 rows). Shipped as CSV in `inst/extdata`;
#' generated by `data-raw/driving_sim.R` (seed 20261025).
#'
#' @format A CSV file with 480 rows and 7 columns:
#' \describe{
#'   \item{vp_id}{Participant id, `"vp01"` to `"vp40"`.}
#'   \item{age}{Age in years; `NA` for `vp17`.}
#'   \item{gender}{`"w"`, `"m"` or `"d"`.}
#'   \item{condition}{TOR modality: `"visuell"`, `"auditiv"`, `"haptisch"`.}
#'   \item{trial}{Repetition within condition, 1-4 (time / learning effect).}
#'   \item{rt_ms}{Take-over reaction time in ms; 12 `NA` (sensor dropouts).}
#'   \item{lane_dev}{Standard deviation of lateral position in m; 9 `NA`.}
#' }
#' Built-in effects: visual TOR slower than auditory, haptic fastest;
#' reaction time decreases over trials (random slope per participant) and
#' increases with age; lane deviation correlates with reaction time.
#' @usage NULL
#' @keywords datasets
#' @seealso [rtrainer_data()]
#' @examples
#' d <- read.csv(rtrainer_data("driving_sim.csv"))
#' str(d)
#' @name driving_sim
NULL

#' Path to a data file shipped with rtrainer
#'
#' Inside exercises (`setup:`) the same function is available in the
#' worker process, so exercises can use
#' `read.csv(rtrainer_data("driving_sim.csv"))`.
#'
#' @param name File name in `inst/extdata`, e.g. `"driving_sim.csv"`.
#' @return Absolute path; error if the file does not exist.
#' @export
rtrainer_data <- function(name) {
  system.file("extdata", name, package = "rtrainer", mustWork = TRUE)
}
